  /* ========== RESET & BASE ========== */
  *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
  :root {
    --primary: #6C63FF; --secondary: #FF6584; --accent: #43E97B;
    --dark: #1a1a2e; --light: #f5f5f5; --text: #333; --white: #fff;
    --radius: 12px; --shadow: 0 8px 30px rgba(0,0,0,0.12);
    --transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  }
  html { scroll-behavior: smooth; }
  body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    color: var(--text); background: var(--light); line-height: 1.6;
  }
  a { text-decoration: none; color: inherit; }
  ul { list-style: none; }
  img { max-width: 100%; }
  .container { max-width: 1200px; margin: 0 auto; padding: 0 20px; }
  section { padding: 80px 0; }
  .section-title {
    text-align: center; font-size: 2.5rem; margin-bottom: 50px;
    background: linear-gradient(135deg, var(--primary), var(--secondary));
    -webkit-background-clip: text; -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  /* ========== NAVBAR ========== */
  .navbar {
    position: fixed; top: 0; width: 100%; z-index: 1000;
    background: rgba(26,26,46,0.95); backdrop-filter: blur(10px);
    padding: 15px 0; transition: var(--transition);
  }
  .navbar.scrolled { padding: 10px 0; background: rgba(26,26,46,0.99); box-shadow: 0 2px 20px rgba(0,0,0,0.3); }
  .navbar .container { display: flex; justify-content: space-between; align-items: center; }
  .navbar .logo { font-size: 1.6rem; font-weight: 700; color: var(--white); }
  .navbar .logo span { color: var(--accent); }
  .nav-links { display: flex; gap: 30px; }
  .nav-links a { color: #ccc; font-weight: 500; transition: var(--transition); position: relative; }
  .nav-links a::after {
    content: ''; position: absolute; bottom: -5px; left: 0;
    width: 0; height: 2px; background: var(--accent); transition: var(--transition);
  }
  .nav-links a:hover { color: var(--white); }
  .nav-links a:hover::after { width: 100%; }
  .hamburger { display: none; flex-direction: column; cursor: pointer; gap: 5px; }
  .hamburger span { width: 25px; height: 3px; background: var(--white); transition: var(--transition); }

  /* ========== HERO ========== */
  .hero {
    min-height: 100vh; display: flex; align-items: center; justify-content: center;
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    position: relative; overflow: hidden; text-align: center; color: var(--white);
  }
  .hero::before {
    content: ''; position: absolute; width: 400px; height: 400px;
    background: radial-gradient(circle, var(--primary), transparent);
    border-radius: 50%; opacity: 0.2; animation: float 6s ease-in-out infinite;
  }
  .hero::after {
    content: ''; position: absolute; width: 300px; height: 300px;
    background: radial-gradient(circle, var(--secondary), transparent);
    border-radius: 50%; opacity: 0.15; animation: float 8s ease-in-out infinite reverse;
    top: 100px; right: 100px;
  }
  @keyframes float {
    0%, 100% { transform: translateY(0) scale(1); }
    50% { transform: translateY(-30px) scale(1.1); }
  }
  .hero-content { position: relative; z-index: 1; }
  .hero-content h1 {
    font-size: 3.5rem; font-weight: 800; margin-bottom: 20px;
    animation: fadeInUp 1s ease;
  }
  .hero-content h1 span {
    background: linear-gradient(135deg, var(--accent), var(--primary));
    -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;
  }
  .hero-content p { font-size: 1.2rem; color: #aaa; margin-bottom: 40px; animation: fadeInUp 1s ease 0.2s both; }

  /* ========== BUTTONS ========== */
  .btn {
    display: inline-block; padding: 14px 36px; border-radius: 50px;
    font-size: 1rem; font-weight: 600; cursor: pointer; border: none;
    transition: var(--transition); position: relative; overflow: hidden;
  }
  .btn-primary {
    background: linear-gradient(135deg, var(--primary), #8B83FF);
    color: var(--white); box-shadow: 0 4px 20px rgba(108,99,255,0.4);
  }
  .btn-primary:hover { transform: translateY(-3px); box-shadow: 0 8px 30px rgba(108,99,255,0.6); }
  .btn-outline {
    background: transparent; color: var(--primary); border: 2px solid var(--primary);
  }
  .btn-outline:hover { background: var(--primary); color: var(--white); transform: translateY(-3px); }
  .btn-gradient {
    background: linear-gradient(135deg, var(--accent), #00d2ff);
    color: var(--dark); box-shadow: 0 4px 20px rgba(67,233,123,0.4);
  }
  .btn-gradient:hover { transform: translateY(-3px) scale(1.05); box-shadow: 0 8px 30px rgba(67,233,123,0.6); }
  .btn-glow {
    background: var(--dark); color: var(--accent); border: 1px solid var(--accent);
  }
  .btn-glow:hover { box-shadow: 0 0 30px rgba(67,233,123,0.5); text-shadow: 0 0 10px var(--accent); }
  .btn-icon {
    background: linear-gradient(135deg, var(--secondary), #ff9a9e);
    color: var(--white); border-radius: 50%; width: 50px; height: 50px;
    padding: 0; display: inline-flex; align-items: center; justify-content: center;
    font-size: 1.2rem;
  }
  .btn-ripple {
    background: linear-gradient(135deg, #f093fb, #f5576c); color: var(--white);
  }
  .btn-ripple::after {
    content: ''; position: absolute; top: 50%; left: 50%;
    width: 0; height: 0; background: rgba(255,255,255,0.3);
    border-radius: 50%; transform: translate(-50%, -50%);
    transition: width 0.6s, height 0.6s;
  }
  .btn-ripple:active::after { width: 300px; height: 300px; }
  .btn-shimmer {
    background: linear-gradient(90deg, var(--dark), #2a2a4a, var(--dark));
    background-size: 200% auto; color: var(--white);
    animation: shimmer 2s linear infinite;
  }
  @keyframes shimmer { 0% { background-position: 0% center; } 100% { background-position: 200% center; } }

  /* ========== ANIMATIONS ========== */
  @keyframes fadeInUp {
