  .animate-pulse { animation: pulse 2s ease-in-out infinite; }

  /* ========== CARDS ========== */
  .cards-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 30px; }
  .card {
    background: var(--white); border-radius: var(--radius); overflow: hidden;
    box-shadow: var(--shadow); transition: var(--transition);
  }
  .card:hover { transform: translateY(-10px); box-shadow: 0 20px 60px rgba(0,0,0,0.2); }
  .card-img { height: 200px; background-size: cover; background-position: center; }
  .card-body { padding: 25px; }
  .card-body h3 { font-size: 1.3rem; margin-bottom: 10px; }
  .card-body p { color: #666; font-size: 0.95rem; margin-bottom: 15px; }
  .card-tag {
    display: inline-block; padding: 4px 14px; border-radius: 20px;
    font-size: 0.8rem; font-weight: 600; margin-right: 5px; margin-bottom: 5px;
  }
  .tag-purple { background: #ede9ff; color: var(--primary); }
  .tag-green { background: #d4f5e5; color: #059669; }
  .tag-pink { background: #fce4ec; color: var(--secondary); }
  .tag-blue { background: #dbeafe; color: #2563eb; }

  /* Gradient card variant */
  .card-gradient {
    background: linear-gradient(135deg, var(--primary), #8B83FF);
    color: var(--white); border-radius: 20px; padding: 40px;
    position: relative; overflow: hidden;
  }
  .card-gradient::before {
    content: ''; position: absolute; top: -50%; right: -50%;
    width: 200px; height: 200px; background: rgba(255,255,255,0.1);
    border-radius: 50%;
  }
  .card-gradient::after {
    content: ''; position: absolute; bottom: -30%; left: -30%;
    width: 150px; height: 150px; background: rgba(255,255,255,0.07);
    border-radius: 50%;
  }
  .card-gradient h3 { font-size: 1.5rem; margin-bottom: 15px; position: relative; z-index: 1; }
  .card-gradient p { color: rgba(255,255,255,0.8); position: relative; z-index: 1; }

  /* Glass card */
  .card-glass {
    background: rgba(255,255,255,0.15); backdrop-filter: blur(10px);
    border: 1px solid rgba(255,255,255,0.2); border-radius: 20px;
    padding: 40px; color: var(--white); text-align: center;
    transition: var(--transition);
  }
  .card-glass:hover { background: rgba(255,255,255,0.25); transform: scale(1.05); }
  .card-glass .icon { font-size: 3rem; margin-bottom: 20px; }
  .card-glass h3 { margin-bottom: 10px; }

  /* 3D tilt card */
  .card-3d { perspective: 1000px; }
  .card-3d-inner {
    transition: transform 0.5s ease; transform-style: preserve-3d;
